/// <summary>
/// PaffH 21.04.23
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(NDXDataTransferErrorLine), DataEventType::ModifiedField)]
public static void NDXDataTransferErrorLine_onModifiedField(Common sender, DataEventArgs e)
{
    NDXDataTransferErrorLine nDXDataTransferErrorLineLocal;
    NDXDataTransferError nDXDataTransferError;
    ModifyFieldEventArgs event = e as ModifyFieldEventArgs;
    NDXDataTransferErrorLine nDXDataTransferErrorLine = sender as NDXDataTransferErrorLine;
    FieldId fieldId = event.parmFieldId();

    switch(fieldId)
    {
        case fieldNum(NDXDataTransferErrorLine,ErrorDone) :
            select firstonly count(RecId) from nDXDataTransferErrorLineLocal 
                where nDXDataTransferErrorLineLocal.NDXDataTransferError == nDXDataTransferErrorLine.NDXDataTransferError
                && nDXDataTransferErrorLineLocal.RecId != nDXDataTransferErrorLine.RecId
                && nDXDataTransferErrorLineLocal.ErrorDone == NoYes::No;
            int errorNotDone = nDXDataTransferErrorLineLocal.RecId + nDXDataTransferErrorLine.ErrorDone == NoYes::No ? 1 : 0;
            select firstonly forupdate nDXDataTransferError
                    where nDXDataTransferError.RecId == nDXDataTransferErrorLine.NDXDataTransferError;
            nDXDataTransferError.ErrorDone = (errorNotDone == 0) ? NoYes::Yes : NoYes::No;
            if (nDXDataTransferError.orig().ErrorDone != nDXDataTransferError.ErrorDone)
            {
                ttsbegin;
                nDXDataTransferError.update();
                ttscommit;
            }
            break;
    }
}
